# create-restaurant-manager-roles-page.ps1
# ONE-SHOT script: decodes the edited infographic image AND writes the HTML poster page
# Run from: C:\Users\admin\Desktop\nigelthomas-portfolio
# Usage: .\create-restaurant-manager-roles-page.ps1

$ErrorActionPreference = "Stop"

$utf8NoBom = New-Object System.Text.UTF8Encoding $false

# ---------- STEP 1: Write the edited image (base64-embedded, decoded to binary) ----------
if (-not (Test-Path ".\assets")) { New-Item -ItemType Directory -Path ".\assets" | Out-Null }

$imgBase64 = ""

$imgBytes = [System.Convert]::FromBase64String($imgBase64)
$imgPath = Join-Path (Get-Location) "assets\roles-responsibilities-restaurant-manager.jfif"
[System.IO.File]::WriteAllBytes($imgPath, $imgBytes)
Write-Host "Created: $imgPath" -ForegroundColor Green

# ---------- STEP 2: Write the HTML poster page ----------
$html = @'
